// Every std/os symbol is documented as an entry of its own.  Keep the
// metadata explicit even where several operations share an implementation
// helper: signatures, capabilities, limits, ownership, and failure behavior
// are part of each public contract.

const fn = (name, syntax, returns, summary, parameters, returnValue, details, example) => ({
  name,
  syntax,
  summary,
  parameters,
  returns,
  returnValue,
  details: Array.isArray(details) ? details : [details],
  example,
});

const constant = (name, type, value, summary, example) => ({
  kind: 'constant',
  name,
  syntax: name,
  summary,
  parameters: 'No arguments; this is a module constant.',
  returns: type,
  returnValue: value,
  details: [`The value is stable for the selected target platform. ${summary}`],
  example,
});

const resource = (name, syntax, returns, summary, parameters, returnValue, details, example) => ({
  kind: 'resource',
  name,
  syntax,
  summary,
  parameters,
  returns,
  returnValue,
  details: Array.isArray(details) ? details : [details],
  example,
});

